import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"无法连接数据库","description":"","frontmatter":{"title":"无法连接数据库"},"headers":[],"relativePath":"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/cannot-connect-database.md","filePath":"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/cannot-connect-database.md","lastUpdated":1788259091000}'),t={name:"ops-knowledge-base/cloud-native/cloud-db-mysql-plus/cannot-connect-database.md"};function c(p,l,d,s,n,r){return i(),o("div",null,[...l[0]||(l[0]=[a('<p>在实际业务场景中，可能会出现无法连接 MySQL Plus 的情况，您可以参考以下排查思路自行检查，也可以直接提工单联系技术支持。</p><h2 id="排查集群状态" tabindex="-1">排查集群状态 <a class="header-anchor" href="#排查集群状态" aria-label="Permalink to &quot;排查集群状态&quot;">​</a></h2><p>排查方法</p><ol><li><p>登录 AppCenter 集群管理页面，检查目标集群的运行状态是否为活跃。</p></li><li><p>查看集群节点资源状态，检查资源硬盘使用率指标是否已超过85%，硬盘空间已不足。</p></li><li><p>查看实例连接数检查全部连接数等服务指标，并通过查看集群最大连接数，确认连接数是否过满。</p><p>-<code>max_connections</code> 指允许同时连接的客户端总数。如果设定值为 <code>default</code>，表示最大连接数随内存规格变化。</p><p>-<code>max_user_connections</code> 指特定 MySQL 账号允许的最大同时连接数。</p></li></ol><p>可能原因</p><ol><li>MySQL Plus 系统故障、状态异常，以及集群或表被锁定等。</li><li>数据库硬盘使用率超过85%后，数据库可能不可用，不能正常执行连接、写入等操作。</li><li>数据库连接数过满，可能会导致业务侧无法正常连接，也会导致实例全量备份和增量备份失败，影响业务的正常使用。</li></ol><p>解决办法</p><ol><li>选中目标集群，选择更多操作 &gt; 重启，尝试重启数据库。</li><li>扩容集群硬盘空间，提升高硬盘可使用空间；删除过期数据；缩短 binlog 本地保留时长；对 CPU 、内存、硬盘等资源指标开启监控告警，及时了解集群资源状态。</li><li>排查业务连接是否有效，释放空闲连接；设置 <code>default</code> ，并扩容集群内存空间，提高 <code>max_connections</code> 值；对当前线程连接数等服务指标开启监控告警，及时了解集群服务状态。</li></ol><h2 id="排查连接方式" tabindex="-1">排查连接方式 <a class="header-anchor" href="#排查连接方式" aria-label="Permalink to &quot;排查连接方式&quot;">​</a></h2><p>排查方法</p><ol><li>检查已安装 MySQL 客户端版本是否低于集群 MySQL 版本。</li><li>登录 AppCenter 集群管理页面，检查目标集群是否开启 SSL 加密传输，以及检查用户账号是否开启加密认证。</li><li>检查连接命令是否正确。</li><li>在集群账号列表，检查连接用户账号是否正确授权或被删除。</li></ol><p>可能原因</p><ol><li>MySQL 客户端版本低于集群 MySQL 版本，兼容性问题导致不能正常连接。</li><li>集群开启 SSL 加密传输后，用户账号未开启加密认证，或未正确上传证书或连接命令不完整。</li><li>连接命令不正确。</li><li>用户账号未被授权为<code>%</code>；用户账号被删除，不支持连接。</li></ol><p>解决办法</p><ol><li>确认数据库内核版本，重新选择 MySQL 客户端相应版本并安装。</li><li>同时开启集群 SSL 加密传输和数据库账户加密认证，且需将 SSL 证书上传到服务器。</li><li>获取正确的连接地址、端口参数配置、用户账号和密码、SSL 证书名等信息，并重试连接实例。</li><li>修改用户账号授权为<code>%</code>；重新添加用户账号；获取可连接用户账号和密码。</li></ol><p>正确连接方式示例：</p><ul><li>开启 SSL 加密传输后，通过外网地址连接：<code>mysql -h &lt;外网地址&gt; -P 3306 -u testuser -p --ssl-ca=ca.pem --ssl-cert=client-cert.pem --ssl-key=client-key.pem</code></li><li>开启 SSL 加密传输后，通过内网地址连接：<code>mysql -h &lt;外网地址&gt; -P 3306 -u testuser -p --ssl-ca=ca.pem --ssl-cert=client-cert.pem --ssl-key=client-key.pem</code></li></ul><blockquote><p>注意</p><p>SSL 证书文件需上传到服务器，且需放在执行连接命令的路径下。</p></blockquote><h2 id="排查网络问题" tabindex="-1">排查网络问题 <a class="header-anchor" href="#排查网络问题" aria-label="Permalink to &quot;排查网络问题&quot;">​</a></h2><h3 id="内网地址连接" tabindex="-1">内网地址连接 <a class="header-anchor" href="#内网地址连接" aria-label="Permalink to &quot;内网地址连接&quot;">​</a></h3><p>排查方法</p><ol><li>检查云服务器与目标 MySQL Plus 集群是否在同一区域同一 VPC 网络。</li><li>检查云服务器关联安全组规则。</li><li>通过 <code>telnet &lt;内网地址&gt; &lt;端口号&gt;</code>命令，检查当前云服务是否可正常连接到数据库端口。</li></ol><p>可能原因</p><ol><li>不同区域或不同 VPC 网络的云资源之间网络隔离，内网互不相通，无法连接。</li><li>云服务器关联安全组未允许对外访问目标集群。</li><li>云服务器无法访问集群开放端口。</li></ol><p>解决办法</p><ol><li>根据就近原则，迁移数据库资源或重新购买云服务器，使其在同一 VPC 网络内；通过 VPC 网络的<code>隧道服务</code>和 <code>VPN 服务</code>，打通资源间不同区域或不同 VPC 的网络。</li><li>为云服务器安全组添加上行规则，允许访问目标集群。</li><li>若云服务器无法连接目标数据库端口，请提工单联系技术支持。</li></ol><h3 id="外网地址连接" tabindex="-1">外网地址连接 <a class="header-anchor" href="#外网地址连接" aria-label="Permalink to &quot;外网地址连接&quot;">​</a></h3><p>排查方法</p><ol><li>IP 白名单添加<code>0.0.0.0/0</code>，检查是否能正常连接。</li><li>检查云服务器关联安全组规则。</li><li>检查云服务器子网关联网络 ACL 规则。</li><li>同区域云服务器进行 ping 集群 IP 测试验证。</li></ol><p>可能原因</p><ol><li>外部服务器 IP 地址变动等，导致白名单中配置不正确。</li><li>云服务器关联安全组未允许对外访问目标集群。</li><li>云服务器绑定的私有网络启用了网络 ACL，但未设置允许对外访问目标集群。</li><li>区域内 VPC 网络不通。</li></ol><p>解决办法</p><ol><li><p>白名单添加<code>0.0.0.0/0</code>后，确认连接情况。</p><p>-正常连接，则在成功连接的客户端，执行<code>show processlist</code>查询进程信息。在 Host 行获取服务器正确 IP 地址，并将其添加到白名单。</p><p>-不能连接，则请排查其他可能原因。</p><blockquote><p>说明</p><p><code>0.0.0.0/0</code>表示允许任何服务器连接数据库。验证结束后，建议立即删除白名单中配置。</p></blockquote></li><li><p>为当前云服务器安全组添加上行规则，允许访问目标集群。</p></li><li><p>关闭云服务器私有网络；对已启用的网络 ACL添加上行规则，放通与目标集群的网络。</p></li><li><p>若同区域云服务器也不能 ping 通集群，请提工单联系技术支持。</p></li></ol>',33)])])}const S=e(t,[["render",c]]);export{h as __pageData,S as default};
